const body = $('Webhook').item.json.body;
const ctx = $input.first().json;

const fornecedores = ctx.fornecedores || [];
const thresholds = ctx.thresholds || {};
const pesos = ctx.pesos || {};
const tabelasPontos = ctx.tabelas_pontos || {};

const DECISOES = {
  elegivel: "Elegível",
  elegivel_condicionado: "Elegível condicionado",
  atencao: "Atenção",
  nao_elegivel: "Não elegível",
  nao_elegivel_gate: "Não elegível (gate)",
};

const resumo = fornecedores.map((f) => ({
  id: f.id,
  nome: f.nome_fantasia || f.razao_social,
  cnpj: f.cnpj,
  score_total: f.score_total,
  decisao: f.decisao,
  decisao_label: DECISOES[f.decisao] || f.decisao,
  status: f.status,
  preliminar: f.preliminar,
  dimensoes: {
    d1_fiscal: f.s1_fiscal,
    d2_financeira: f.s2_financeira,
    d3_regime: f.s3_regime,
    d4_dependencia: f.s4_dependencia,
    d5_maturidade: f.s5_maturidade,
  },
}));

const contextoJson = JSON.stringify({
  cliente_id: body.cliente_id,
  total_fornecedores: fornecedores.length,
  metodologia: {
    pesos_por_dimensao: {
      D1_fiscal: pesos.w_d1,
      D2_financeira: pesos.w_d2,
      D3_regime: pesos.w_d3,
      D4_dependencia: pesos.w_d4,
      D5_maturidade: pesos.w_d5,
      observacao: "Se o fornecedor ainda não respondeu o questionário (D5 nulo), os pesos de D1-D4 são redistribuídos proporcionalmente e o score fica marcado como preliminar.",
    },
    tabelas_pontos_por_criterio: tabelasPontos,
    reguas_decisao: thresholds,
  },
  fornecedores: resumo,
}, null, 2);

// Manual do sistema — base de conhecimento estática sobre "como usar o portal".
// Ajuste este texto livremente (fica só aqui no código, sem depender de outra tabela).
const manualDoSistema = `
# Manual do Portal Cred Score (BMS)

## O que é
O Cred Score analisa o risco de crédito de fornecedores de uma empresa-cliente, combinando 5 dimensões:
- D1 · Fiscal: regularidade fiscal (CND federal/estadual/municipal, dívida ativa PGFN, Receita Sintonia, obrigações acessórias).
- D2 · Financeira: Serasa Score, protestos, execuções relevantes, negativação SPC.
- D3 · Regime: enquadramento tributário do fornecedor (Simples, Lucro Presumido, Lucro Real etc).
- D4 · Dependência: quanto o fornecedor depende financeiramente do cliente (participação das compras no faturamento estimado do fornecedor).
- D5 · Maturidade: questionário respondido pelo próprio fornecedor sobre práticas de gestão/compliance.
Cada dimensão gera uma nota; o score final é a média ponderada pelos pesos ativos, comparado às réguas de decisão pra virar uma DECISÃO: Elegível, Elegível condicionado, Atenção, Não elegível, ou Não elegível (gate — quando algum critério crítico bloqueia o fornecedor independente da nota).

## Cadastro de fornecedores
- Cadastro individual: informar CNPJ e valor de compras anual (obrigatório, usado no cálculo de D4).
- Cadastro em lote: upload de planilha/CSV com CNPJ + razão social + valor de compras anual por linha; o sistema aponta linhas inválidas ou CNPJs já cadastrados antes de importar.

## Análise de um fornecedor
- Ao cadastrar um fornecedor (ou clicar em "Solicitar nova análise"), o sistema dispara automaticamente a coleta de dados e o cálculo do score — não precisa fazer nada manual além de solicitar.
- O andamento aparece em etapas (ex: "Na fila" → "Fiscal (D1)" → "Financeira (D2)" → "Cálculo final") e atualiza em tempo real na tela, sem precisar recarregar a página.
- Se o fornecedor ainda não respondeu o questionário de maturidade (D5), o score sai como "preliminar" (pesos redistribuídos entre D1-D4) e é recalculado automaticamente quando o questionário for respondido.
- "Solicitar nova análise" permite também atualizar o valor de compras anual do fornecedor antes de recalcular.
- Não é possível solicitar uma nova análise se já existir uma em andamento (status "aguardando" ou "processando") para aquele fornecedor.

## Questionário de maturidade (D5)
- O sistema gera um link público (sem necessidade de login) que deve ser enviado ao próprio fornecedor para ele responder.
- As respostas alimentam a nota de D5; o score final é recalculado automaticamente assim que o fornecedor responde.
- O link expira e pode ser revogado; um novo pode ser gerado a qualquer momento pela tela do fornecedor.

## Dashboard
- Mostra estatísticas gerais: quantidade de fornecedores, score médio por dimensão, quantos estão "Não elegíveis", e os fornecedores com maior exposição financeira em situação problemática ("Maior exposição em risco").

## Usuários e permissões
- Perfil "admin_cliente": pode convidar/remover usuários da própria empresa e ver tudo.
- Perfil "analista_cliente": acessa fornecedores e análises, mas não gerencia usuários.
- Só administradores da BMS (equipe interna) editam os pesos das dimensões, as tabelas de pontos por critério e as réguas de decisão — clientes só visualizam a versão vigente desses parâmetros, não editam.

## O que este assistente PODE fazer
Responder perguntas sobre os fornecedores do cliente atual (scores, decisões, comparações), explicar a metodologia (pesos, critérios de pontuação, réguas de decisão) e tirar dúvidas de como usar as telas do portal (cadastro, upload em lote, questionário, solicitar nova análise etc).

## O que este assistente NÃO faz
Não edita cadastros, não solicita análises, não altera parâmetros nem responde questionários por você — essas ações precisam ser feitas nas telas do portal. Se o usuário pedir para "fazer" alguma dessas ações, oriente-o para a tela correta em vez de tentar executar.
`.trim();

const systemPrompt = `Você é o Assistente Cred Score da BMS Consultoria Tributária, dentro do portal do cliente.
Você tem duas fontes de conhecimento abaixo: (1) o MANUAL DO SISTEMA, sobre como o portal funciona e como usar cada funcionalidade; (2) os DADOS DO CLIENTE ATUAL, com fornecedores, análises e a metodologia (pesos/tabelas de pontos/réguas) vigente.
Use o manual para responder dúvidas de "como funciona" / "como faço para" / "o que significa tal status ou decisão". Use os dados do cliente para responder perguntas sobre fornecedores, scores e metodologia aplicada aos números reais.
Nunca invente CNPJs, scores ou decisões que não estejam nos dados. Nunca revele dados de outro cliente: você só tem acesso aos fornecedores do cliente atual, já filtrados abaixo.
Se a pergunta pedir uma AÇÃO (editar, cadastrar, solicitar análise, responder questionário), não finja executá-la — explique em "text" onde na tela o usuário faz isso.
Se a pergunta não puder ser respondida com o que você tem, diga isso claramente em "text" e deixe "blocks" como array vazio.
Responda em português do Brasil, tom profissional e direto.

${manualDoSistema}

DADOS DO CLIENTE ATUAL (já filtrados):
${contextoJson}

Pergunta do usuário (tela atual: "${body.tela}"${body.fornecedor_id ? `, fornecedor em foco: ${body.fornecedor_id}` : ""}):
"${body.pergunta}"

Responda SEMPRE em JSON válido, seguindo exatamente este formato:
{
  "text": "resposta em texto corrido",
  "blocks": [
    { "type": "lista", "items": [ { "id": "...", "nome": "...", "cnpj": "...", "score": 0, "decisao": "elegivel|elegivel_condicionado|atencao|nao_elegivel|nao_elegivel_gate" } ], "totalLabel": "..." }
  ],
  "procedencia": "frase curta explicando a base da resposta, ex: baseado em N análises concluídas e nas réguas ativas, ou 'baseado no manual do portal' pra dúvidas de uso"
}
Use o bloco "detalhe" em vez de "lista" quando a pergunta for sobre UM fornecedor específico:
{ "type": "detalhe", "nome": "...", "cnpj": "...", "decisao": "...", "dimensoes": [ { "label": "D1 · Fiscal", "valor": 0, "max": 100 } ] }
Se a resposta não precisar de nenhum bloco visual (ex: pergunta sobre metodologia/critérios/uso do portal), retorne "blocks": [].`;

return [{ json: { systemPrompt, registro_id: body.registro_id, pergunta: body.pergunta } }];

const registroId = $('Montar Prompt do Agente').item.json.registro_id;
let text = "Não consegui montar uma resposta agora.";
let blocks = [];
let procedencia = null;
let status = "concluido";

try {
  const out = $input.first().json;
  const parsed = out.output ?? out;
  text = String(parsed.text ?? "").trim() || "Não encontrei informações suficientes para responder.";
  blocks = Array.isArray(parsed.blocks) ? parsed.blocks : [];
  procedencia = parsed.procedencia ?? null;
} catch (err) {
  status = "erro";
  text = "Não foi possível interpretar a resposta do assistente. Tente reformular a pergunta.";
  blocks = [];
}

// Escapa qualquer string pra uso seguro dentro de literal SQL '...'
// (aspas simples dobradas — nunca usar aspas duplas: em Postgres isso é identificador, não string).
const escSql = (v) => (v === null || v === undefined ? "NULL" : `'${String(v).replace(/'/g, "''")}'`);

const sql = `UPDATE public."bms-historico_mensagens"
SET mensagem_agente = ${escSql(text)},
    blocos_resposta = ${escSql(JSON.stringify(blocks))}::jsonb,
    procedencia = ${escSql(procedencia)},
    status = ${escSql(status)}
WHERE id = ${Number(registroId)};`;

return [{ json: { registro_id: registroId, text, blocks, procedencia, status, sql } }];

